import{z as A,x as l,o,c as E,q as r,j as i,D as e,d as t,s as n,S as h}from"./chunks/framework.C8m1ZpeB.js";const k=JSON.parse('{"title":"Aho–Corasick","description":"","frontmatter":{"title":"Aho–Corasick","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/aho-corasick.md","filePath":"cs/aho-corasick.md","lastUpdated":1791413859000}'),c={name:"cs/aho-corasick.md"};function d(p,a,B,_,C,m){const s=l("Mermaid");return o(),E("div",null,[a[2]||(a[2]=r('<h1 id="aho–corasick" tabindex="-1">Aho–Corasick <a class="header-anchor" href="#aho–corasick" aria-label="Permalink to &quot;Aho–Corasick&quot;">​</a></h1><div class="epigraph"><p>多模式先建成一棵带失败边的 trie；扫文本一次，沿转移与失败链输出所有命中。</p><footer>—— 据 Aho and Corasick, Efficient String Matching: An Aid to Bibliographic Search, 1975；CLRS 第 32 章整理</footer></div><p>上一课<a href="/cs/boyer-moore">Boyer–Moore</a>优化单模式跳读。\\(k\\) 个模式各跑一遍，总代价随 \\(k\\) 倍增，且共享前缀被重复比。本课不重做坏字符表。缺口是<strong>一机多模式</strong>：把 \\(P_1,\\ldots,P_k\\) 做成自动机，扫 \\(T\\) 线性于 \\(n\\) 加命中次数。后课离开串，进入贪心范式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/trie">Trie</a> 已能插入多个串。匹配时失配不能只退回根：当前节点代表的前缀的真后缀可能是另一模式的前缀。Aho–Corasick：每个节点一条失败边，指向「最长真后缀」对应的节点（KMP 的 \\(\\pi\\) 在树上的推广）。扫描：\\(T\\) 的下一字符有转移则走，否则跟失败边直到有或到根。节点若标记模式结束（或失败链上有结束），报告命中。</p><p><span class="marginnote">术语翻译：失败边是「失配时该跳到哪」的预计算答案——它指向当前已匹配串的最长真后缀中、同时又是某个模式前缀的那个节点。KMP 里叫 next/π 数组，Aho–Corasick 把它从一条串搬到一棵 trie 上，多模式共享同一套回退机制。</span></p><p>缺口是失败函数，不是再写 \\(k\\) 次 KMP。预处理对模式总长 \\(m\\) 线性（字母表当常数或用 map 则多对数）。扫描 \\(O(n+z)\\)，\\(z\\) 为输出个数。</p><h3 id="失败边不是父指针" tabindex="-1">失败边不是父指针 <a class="header-anchor" href="#失败边不是父指针" aria-label="Permalink to &quot;失败边不是父指针&quot;">​</a></h3><p>父指针回退会丢掉「后缀也是前缀」。失败边可能跳到另一分支。输出链：沿失败边收集所有结束标记，避免漏掉被当前前缀包含的短模式。</p><p><span class="marginnote">Aho–Corasick 1975，CACM。与 KMP 同一自匹配思想，对象从串换成 trie。后课词法的「多种记号」是正则并，不是本课的精确多模式词典。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>将模式插入 trie，根的失败为根。BFS 按层算失败：孩子 \\(c\\) 的失败 = 父失败沿 \\(c\\) 能走到的节点。再扫 \\(T\\)。</p><p><span class="marginnote">常见误区：初学者容易以为失配时要把文本指针往回退。实际上文本指针只前进、从不回退，回退的只是自动机状态——这正是扫描保持 \\(O(n)\\) 的原因；代价被摊还掉，因为状态深度每步至多加一，跟失败边却至少减一。</span></p>',13)),(o(),i(h,null,{default:e(()=>[n(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PS%5B%22%E6%A8%A1%E5%BC%8F%E9%9B%86%22%5D%20--%3E%20TR%5B%22Trie%22%5D%0A%20%20TR%20--%3E%20FAIL%5B%22BFS%20%E5%A4%B1%E8%B4%A5%E8%BE%B9%22%5D%0A%20%20FAIL%20--%3E%20SCAN%5B%22%E4%B8%80%E6%AC%A1%E6%89%AB%20T%22%5D%0A%20%20SCAN%20--%3E%20OUT%5B%22%E6%B2%BF%E8%BE%93%E5%87%BA%E9%93%BE%E6%8A%A5%E5%91%8A%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p>二进制字母表或 Unicode 的转移表要权衡空间；本课渐近把 \\(|\\Sigma|\\) 当实现参数。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>摊还：失败边使状态上的「当前匹配长度」不增得太快，与 KMP 的 \\(q\\) 同类。不要对每个位置把失败链走到底而不记账——输出链应预处理成直接链表。重叠命中（<code>aa</code> 在 <code>aaa</code>）必须都报，除非题目去重。</p><p>与 BM：多模式上 BM 没有这份自动机；词典检索用本课。</p><p>失败边到底怎么救场？看模式集 {he, she, his} 的自动机：实线是 trie 转移，虚线是失败边。读入 <code>she</code> 走到 she 节点时，失败链会顺路带出藏在里面的短模式 he：</p>',5)),(o(),i(h,null,{default:e(()=>[n(s,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%A0%B9%20%E2%88%85%22%5D%20--%3E%7C%22h%22%7C%20H%5B%22h%22%5D%0A%20%20R%20--%3E%7C%22s%22%7C%20S%5B%22s%22%5D%0A%20%20H%20--%3E%7C%22e%22%7C%20HE%5B%22he%20%E2%98%85%E5%91%BD%E4%B8%AD%22%5D%0A%20%20H%20--%3E%7C%22i%22%7C%20HI%5B%22hi%22%5D%0A%20%20HI%20--%3E%7C%22s%22%7C%20HIS%5B%22his%20%E2%98%85%E5%91%BD%E4%B8%AD%22%5D%0A%20%20S%20--%3E%7C%22h%22%7C%20SH%5B%22sh%22%5D%0A%20%20SH%20--%3E%7C%22e%22%7C%20SHE%5B%22she%20%E2%98%85%E5%91%BD%E4%B8%AD%22%5D%0A%20%20H%20-.%E5%A4%B1%E8%B4%A5.-%3E%20R%0A%20%20S%20-.%E5%A4%B1%E8%B4%A5.-%3E%20R%0A%20%20HE%20-.%E5%A4%B1%E8%B4%A5.-%3E%20R%0A%20%20HI%20-.%E5%A4%B1%E8%B4%A5.-%3E%20R%0A%20%20SH%20-.%E5%A4%B1%E8%B4%A5.-%3E%20H%0A%20%20SHE%20-.%E5%A4%B1%E8%B4%A5.-%3E%20HE%0A%20%20HIS%20-.%E5%A4%B1%E8%B4%A5.-%3E%20S%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p><span class="marginnote">数字实例：拿这棵自动机扫文本 ushers——u 停在根，s 进 s，h 进 sh，e 进 she（命中 she，沿输出链带出 he），r 无处可走弹回根，s 又进 s。六次读入、两次输出，文本指针从未回退，短模式也没漏报。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不做正则、不写近似、不处理通配符。失败函数假定精确字符相等。后课默认：多模式精确匹配一次扫描；贪心作为设计法的正确性从下一课单独论证，不再扫串。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多模式 = trie + 失败边（KMP 在树上）。</li><li>预处理线性于模式总长；扫描线性于文本加输出。</li><li>精确词典，不是正则词法。</li><li>出处：Aho and Corasick, 1975；CLRS 第 32 章。</li></ul>',5))])}const T=A(c,[["render",d]]);export{k as __pageData,T as default};
